// Turns the Liaisons lookup into { lie, email, session }.
// Unlinked chats search with a sentinel: an empty email would match every request without one.
const chatId = $('Sub Start').first().json.chatId;
const l = $input.first().json || {};
if (!l.Email) return [{ json: { lie: false, chatId: chatId, filtre: '__aucun__' } }];
return [{ json: {
  lie: true, chatId: chatId, email: l.Email, prenom: l.Prenom || '', filtre: l.Email, recordId: l.id,
  session: { plat: l['Session plat'] || '', creneau: l['Session creneau'] || '', etapes: l['Session etapes'] || '', etape: Number(l['Session etape']) || 0 }
} }];

// Most recent ready plan for this account ("Cree le" first, reference as tie-break: MP-YYYYMMDD-...).
const demandes = $input.all().map(function (i) { return i.json; }).filter(function (d) { return d.Reference; });
demandes.sort(function (a, b) {
  const ca = String(a['Cree le'] || ''), cb = String(b['Cree le'] || '');
  if (ca !== cb) return cb.localeCompare(ca);
  return String(b.Reference).localeCompare(String(a.Reference));
});
const d = demandes[0];
if (!d) return [{ json: { reference: '', filtre: '__aucune__' } }];
return [{ json: { reference: d.Reference, filtre: d.Reference, personnes: d.Personnes || null, statut: d.Statut } }];

// Always exactly one item back to the parent.
const compte = $('Extract Account').first().json;
const semaine = $('Latest Plan').first().json;
if (!compte.lie) return [{ json: { lie: false, plan: false } }];
const base = { lie: true, email: compte.email, prenom: compte.prenom, recordId: compte.recordId, session: compte.session };
if (!semaine.reference) return [{ json: Object.assign({ plan: false }, base) }];

const ORDRE_JOURS = ['Lun', 'Mar', 'Mer', 'Jeu', 'Ven', 'Sam', 'Dim'];
const ORDRE_MOMENTS = ['midi', 'soir'];
function rang(c) { const p = String(c || '').split('_'); return ORDRE_JOURS.indexOf(p[0]) * 2 + ORDRE_MOMENTS.indexOf(p[1]); }

const repas = $input.all().map(function (i) { return i.json; }).filter(function (r) { return r.Creneau; }).map(function (r) {
  let ingredients = [];
  try { ingredients = JSON.parse(r.Ingredients || '[]'); } catch (e) { ingredients = []; }
  return {
    creneau: r.Creneau, plat: r.Plat, lien: r['Lien recette'] || '', spoon: Number(r['Spoonacular ID']) || null,
    temps: Number(r.Temps) || null, calories: Number(r.Calories) || null, proteines: Number(r.Proteines) || null,
    ingredients: ingredients
  };
}).sort(function (a, b) { return rang(a.creneau) - rang(b.creneau); });

return [{ json: Object.assign({}, base, {
  plan: repas.length > 0, reference: semaine.reference, personnes: semaine.personnes, statut: semaine.statut, repas: repas
}) }];
